'use strict';
const E=CenterEngine,$=id=>document.getElementById(id),STORE='scm-virtual-center-tab-v1';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),n=v=>Number(v).toLocaleString('ko-KR');
const time=t=>{t=Math.floor(t)%86400;return [Math.floor(t/3600),Math.floor(t/60)%60,t%60].map(v=>String(v).padStart(2,'0')).join(':')};
let s,selectedFloor=0,detail=null,toastTimer,lastSave=0;
try{const saved=sessionStorage.getItem(STORE);s=saved?E.migrateState(JSON.parse(saved)):E.createState();E.validate(s);if(saved)s.running=false}catch(e){s=E.createState()}
const scene=new FacilityScene($('facility'),floor=>selectFloor(floor));
function text(id,value){if($(id).textContent!==String(value))$(id).textContent=value}
function html(id,value){if($(id).innerHTML!==value)$(id).innerHTML=value}
function toast(message){$('toast').textContent=message;$('toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').style.display='none',2800)}
function save(){try{sessionStorage.setItem(STORE,JSON.stringify(s))}catch(e){/* A simulation still runs if browser storage is unavailable. */}}
function selectFloor(floor){selectedFloor=Number(floor);scene.floor=selectedFloor;if(scene.plan&&!selectedFloor){scene.floor=1;selectedFloor=1}document.querySelectorAll('[data-floor]').forEach(b=>b.classList.toggle('active',Number(b.dataset.floor)===selectedFloor));text('sceneTitle',selectedFloor?selectedFloor+'층 · '+E.FLOOR_CONFIG[selectedFloor].name:'센터 전체 보기');text('viewBadge',selectedFloor?selectedFloor+'F / '+({1:'DOCKS',2:'COLD STORAGE',3:'BULKY GOODS',4:'AUTOSTORE'}[selectedFloor]):'ALL FLOORS');const info={0:'1층 입하 3개 · 출하 40개 도크를 기준으로 층별 작업이 연결됩니다.',1:'입하 구역은 한편에 분리 배치합니다. 검수·패킹·집결 후 노선별 출하로 이어집니다.',2:'냉동·냉장 구역을 나누고, 각 상품의 보관존에서 피킹 후 1층으로 이송합니다.',3:'부피가 큰 상품은 대형 랙과 팔레트 구역에서 피킹합니다. 동시 작업 2건은 데모 값입니다.',4:'그리드 16×10 · 로봇 6대 · 포트 4개는 데모 설정입니다. 작업별 로봇·포트를 중복 없이 배정합니다.'};text('floorInfo',info[selectedFloor]);if([2,3].includes(selectedFloor)&&$('locFloor').value!==String(selectedFloor)){$('locFloor').value=String(selectedFloor);updateLocationZones();renderLocations()}}
function stateClass(state){return state==='SHIPPED'?'shipped':state==='WAIT_STOCK'?'wait':state==='LOADING'||state==='LOADED'?'loading':['PICKING','PACKING','TRANSFER','READY'].includes(state)?'active':''}
function dockState(kind,d){if(d.blocked)return {cls:'blocked',status:'점검 중'};if(!d.truck)return {cls:'',status:'비어 있음'};if(kind==='inbound'){const r=s.receipts.find(r=>r.id===d.truck);return {cls:'inbound',status:r?.plate||'하역 중',sub:'하역·검수 중'}}const t=s.trucks.find(t=>t.id===d.truck);return {cls:t?.loading?'loading':'ready',status:'R'+String(t?.route||0).padStart(2,'0')+' · '+(t?.loading?'상차 중':t?.loaded.length?'상차 완료':'배차 완료'),sub:t?.plate||''}}
function buildDocks(){for(const kind of ['inbound','outbound']){const target=kind==='inbound'?'inboundDocks':'outboundDocks';$(target).innerHTML=s.docks[kind].map(d=>`<button class="dock" data-dock="${d.id}" data-kind="${kind}" aria-label="${d.id} 도크 상세"><b>${d.id}</b><span>비어 있음</span></button>`).join('');$(target).querySelectorAll('[data-dock]').forEach(b=>b.onclick=()=>openDetail({type:'dock',kind:b.dataset.kind,id:b.dataset.dock}))}}
function updateDocks(){for(const kind of ['inbound','outbound'])for(const d of s.docks[kind]){const button=document.querySelector('[data-dock="'+d.id+'"]'),v=dockState(kind,d);if(button.className!=='dock '+v.cls)button.className='dock '+v.cls;button.querySelector('span').textContent=v.status;button.title=d.id+' · '+v.status+(v.sub?' · '+v.sub:'')}}
function render(){const m=E.metrics(s);text('clock',time(s.time));text('mActive',n(m.active));text('mShipped',n(m.shipped));text('mWait','재고 대기 '+m.stockWait);text('mTotal','접수 '+m.orders+'건');text('mIn',m.inOccupied);text('mOut',m.outOccupied);text('mInQueue','대기 차량 '+m.inQueue);text('mOutQueue','대기 차량 '+m.outQueue);$('orderBar').style.width=(m.orders?m.active/m.orders*100:0)+'%';$('shipBar').style.width=(m.orders?m.shipped/m.orders*100:0)+'%';$('inBar').style.width=m.inOccupied/3*100+'%';$('outBar').style.width=m.outOccupied/40*100+'%';text('pickingCount',m.picking+'건');text('pickingQueue','대기 '+m.pickQueue);text('portCount',m.ports+' / 4');text('putawayCount',n(m.putawayQty)+'개');text('stockCount',n(m.stockQty)+'개');text('reservedCount','예약 '+n(m.reserved));text('playLabel',s.running?'데모 운영 중':'일시정지');text('play',s.running?'Ⅱ 일시정지':'▶ 운영 시작');$('liveDot').classList.toggle('paused',!s.running);$('speed').value=s.speed;$('autoOrders').checked=s.autoOrders;$('autoDispatch').checked=s.autoDispatch;text('floor4Stats','로봇 '+m.robots+' / 6');text('floor3Stats','피킹 '+s.jobs.filter(j=>j.floor===3).length+'건');text('floor2Stats','피킹 '+s.jobs.filter(j=>j.floor===2).length+'건');updateDocks();
 html('eventList',s.events.slice(0,9).map(e=>`<div class="event"><time>${time(e.time)}</time><i></i><span>${esc(e.message)}</span></div>`).join(''));
 const flow=['WAIT_STOCK','PICKING','TRANSFER','PACKING','READY','LOADING','LOADED','SHIPPED'];html('flowSummary',flow.map(st=>`<span>${E.ORDER_NAMES[st]}<strong>${s.orders.filter(o=>o.state===st).length}</strong></span>`).join(''));text('orderTabCount',s.orders.length);
 html('ordersTable',[...s.orders].reverse().slice(0,40).map(o=>{const done=o.lines.filter(l=>l.state==='PICKED').length,total=o.lines.reduce((a,l)=>a+l.qty,0);return `<tr class="clickable" data-order="${o.id}" tabindex="0"><td class="mono">${o.id}</td><td>${[...new Set(o.lines.map(l=>l.floor))].sort().join('F / ')}F</td><td class="mono">R${String(o.route).padStart(2,'0')}</td><td>${o.lines.length}종 / ${total}개</td><td><span class="progress"><b style="width:${done/o.lines.length*100}%"></b></span>${done}/${o.lines.length}</td><td><span class="state ${stateClass(o.state)}">${E.ORDER_NAMES[o.state]}</span></td></tr>`}).join(''));
 html('stockTable',E.PRODUCTS.map(p=>{const x=s.stock[p.id],cls=p.floor===2?'coldtag':p.floor===3?'goldtag':'minttag';return `<tr><td class="stocktitle">${esc(p.name)}<small>${p.id}</small></td><td class="${cls}">${p.floor}F / ${{FROZEN:'냉동',CHILLED:'냉장',BULKY:'대형',AUTOSTORE:'AutoStore'}[p.zone]}</td><td class="num">${n(x.qty)}</td><td class="num">${n(x.reserved)}</td><td class="num">${n(x.qty-x.reserved)}</td><td class="num">${n(x.received)}</td><td class="num">${n(x.picked)}</td></tr>`}).join(''));
 html('inboundsTable',[...s.receipts].reverse().slice(0,30).map(r=>`<tr><td class="mono">${r.id}<span class="tiny"> / ${r.plate}</span></td><td>${r.dock||'—'}</td><td>${r.items.reduce((a,i)=>a+i.qty,0)}개</td><td>${[...new Set(r.items.map(i=>E.PRODUCTS.find(p=>p.id===i.sku).floor))].sort().join('F / ')}F</td><td><span class="state ${r.state==='DONE'?'shipped':r.state==='WAIT_DOCK'?'wait':'active'}">${{WAIT_DOCK:'도크 대기',UNLOADING:'하역·검수',PUTAWAY:'층별 적치',DONE:'적치 완료'}[r.state]}</span></td></tr>`).join(''));
 renderLocations();
 }
function detailItem(label,value){return `<div class="detail-item"><span>${label}</span><b>${value}</b></div>`}
function openDetail(ref){detail=ref;const dialog=$('detailDialog');let content='';if(ref.type==='location'){text('dialogEyebrow','LOCATION STOCK · '+ref.id.slice(0,2));content=locationDetail(ref.id)}else if(ref.type==='dock'){const d=s.docks[ref.kind].find(d=>d.id===ref.id),v=dockState(ref.kind,d);text('dialogEyebrow',ref.kind==='inbound'?'1F · INBOUND DOCK':'1F · OUTBOUND DOCK');content=`<h2>${d.id}</h2><p class="dialogdesc">${ref.kind==='inbound'?'입하':'출하'} 도크 · ${v.status}</p>`;if(!d.truck){content+=`<div class="detail-grid">${detailItem('현재 상태',d.blocked?'점검 중':'사용 가능')}${detailItem('위치','1층 '+(ref.kind==='inbound'?'입하장':'출하장'))}</div><div class="helpline">${ref.kind==='inbound'?'입하 차량을 배정하면 하역·검수 후 층별 적치가 진행됩니다.':'노선에 맞는 출하 차량을 배정하면 패킹이 끝난 주문을 상차합니다.'}</div><div class="dialogactions">${ref.kind==='outbound'?'<select id="dockRoute" aria-label="배정 차량 노선">'+Array.from({length:8},(_,i)=>`<option value="${i+1}">R${String(i+1).padStart(2,'0')} 노선</option>`).join('')+'</select>':''}<button id="assignVehicle" class="primary" ${d.blocked?'disabled':''}>${ref.kind==='inbound'?'입하 차량 배정':'출하 차량 배차'}</button><button id="toggleBlock">${d.blocked?'점검 해제':'점검으로 전환'}</button></div>`}else if(ref.kind==='inbound'){const r=s.receipts.find(r=>r.id===d.truck);content+=`<div class="detail-grid">${detailItem('차량',esc(r.plate))}${detailItem('하역·검수 잔여',Math.max(0,Math.ceil(r.until-s.time))+'초')}${detailItem('납품 수량',r.items.reduce((a,i)=>a+i.qty,0)+'개')}${detailItem('다음 단계','층별 적치 → 가용화')}</div><h3>입하 품목</h3><table><tbody>${r.items.map(i=>{const p=E.PRODUCTS.find(p=>p.id===i.sku);return `<tr><td>${esc(p.name)}</td><td>${p.floor}F<small class="destination-code">${esc(i.locationId||'AutoStore')}</small></td><td class="num">${i.qty}개</td></tr>`}).join('')}</tbody></table><p class="helpline">하역이 끝나면 차량은 도크를 비웁니다. 상품은 층별 적치 완료 시점에 가용 재고로 반영됩니다.</p>`}else{const t=s.trucks.find(t=>t.id===d.truck);content+=`<div class="detail-grid">${detailItem('차량',esc(t.plate))}${detailItem('배송 노선','R'+String(t.route).padStart(2,'0'))}${detailItem('상차 완료',t.loaded.length+' / '+t.capacity+'건')}${detailItem('진행 중',t.loading?esc(t.loading):'없음')}</div><h3>상차 주문</h3><p class="helpline">${t.loaded.length?t.loaded.map(esc).join(' · '):'아직 상차를 마친 주문이 없습니다.'}</p><p class="helpline">데모에서는 모의 주문 4건 만재 또는 배차 후 4분 경과 시 상차 완료 주문을 싣고 출발합니다. 상차 중에는 출발할 수 없습니다.</p><div class="dialogactions"><button id="departVehicle" class="primary" ${t.loading?'disabled':''}>${t.loaded.length?'차량 출발':'공차 출발'}</button></div>`}}else if(ref.type==='order'){const o=s.orders.find(o=>o.id===ref.id);text('dialogEyebrow','ORDER TRACE · DEMO');content=`<h2>${o.id}</h2><p class="dialogdesc">${E.ORDER_NAMES[o.state]} · 접수 ${time(o.created)}</p><div class="detail-grid">${detailItem('노선','R'+String(o.route).padStart(2,'0'))}${detailItem('출하 차량',o.truck||'미배정')}${detailItem('상품 수량',o.lines.reduce((a,l)=>a+l.qty,0)+'개')}${detailItem('출하 완료 시각',o.shippedAt?time(o.shippedAt):'—')}</div><h3>층별 피킹 진행</h3><table><thead><tr><th>상품</th><th>층</th><th>수량</th><th>상태</th></tr></thead><tbody>${o.lines.map(l=>`<tr><td>${esc(E.PRODUCTS.find(p=>p.id===l.sku).name)}<small class="destination-code">${(l.allocations||[]).map(a=>esc(a.locationId)+' × '+a.qty).join('<br>')||(l.floor===4?'AutoStore 포트':l.state==='PICKED'?'이전 버전 피킹 · 위치 기록 없음':'위치 배정 대기')}</small></td><td>${l.floor}F</td><td>${l.qty}</td><td>${{WAIT:'재고 대기',QUEUED:'피킹 대기',PICKING:'피킹 중',PICKED:'피킹 완료'}[l.state]}</td></tr>`).join('')}</tbody></table><div class="helpline">여러 층에 걸친 주문은 모든 상품의 피킹이 끝난 뒤 1층으로 이송됩니다.</div>`}
 $('dialogContent').innerHTML=content;if(!dialog.open)dialog.showModal();if(ref.type==='dock'){const d=s.docks[ref.kind].find(d=>d.id===ref.id);if($('assignVehicle'))$('assignVehicle').onclick=()=>{if(ref.kind==='inbound')E.addReceipt(s,d.id);else E.dispatch(s,Number($('dockRoute').value),d.id);render();save();openDetail(ref);toast('가상 차량을 배정했습니다.')};if($('toggleBlock'))$('toggleBlock').onclick=()=>{const ok=E.setBlocked(s,ref.kind,d.id,!d.blocked);render();save();openDetail(ref);if(!ok)toast('차량이 있는 도크는 점검으로 바꿀 수 없습니다.')};if($('departVehicle'))$('departVehicle').onclick=()=>{const ok=E.depart(s,d.truck);render();save();openDetail(ref);toast(ok?'가상 차량이 출발했습니다.':'상태가 변경되었거나 상차 중입니다.')}}
 }
function setTab(tab){document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));for(const id of ['orders','stock','inbounds'])$(id+'Panel').hidden=id!==tab}
function toggleRun(){s.running=!s.running;render();save()}
$('play').onclick=toggleRun;$('speed').onchange=()=>{s.speed=Number($('speed').value);save()};$('autoOrders').onchange=()=>{s.autoOrders=$('autoOrders').checked;s.nextAuto=s.time+60;save();toast(s.autoOrders?'모의 시간 1분마다 주문 3건이 추가됩니다.':'자동 주문을 멈췄습니다.')};$('autoDispatch').onchange=()=>{s.autoDispatch=$('autoDispatch').checked;save()};
$('addOrders').onclick=()=>{const added=E.addOrders(s,10);render();save();toast(added.length+'건의 데모 주문을 추가했습니다.')};$('addInbound').onclick=()=>{E.addReceipt(s);render();save();toast('가상 입하 차량을 추가했습니다.')};$('addOutbound').onclick=()=>{E.dispatch(s);render();save();toast('가상 출하 차량을 추가했습니다.')};
document.querySelectorAll('[data-floor]').forEach(b=>b.onclick=()=>selectFloor(b.dataset.floor));$('view3d').onclick=()=>{scene.plan=false;$('view3d').classList.add('selected');$('viewPlan').classList.remove('selected');selectFloor(selectedFloor)};$('viewPlan').onclick=()=>{scene.plan=true;$('viewPlan').classList.add('selected');$('view3d').classList.remove('selected');selectFloor(selectedFloor||1)};$('zoomIn').onclick=()=>scene.zoom=Math.min(1.7,scene.zoom+.12);$('zoomOut').onclick=()=>scene.zoom=Math.max(.65,scene.zoom-.12);$('cameraReset').onclick=()=>{scene.yaw=.62;scene.zoom=1};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>setTab(b.dataset.tab));$('ordersTable').addEventListener('click',e=>{const row=e.target.closest('[data-order]');if(row)openDetail({type:'order',id:row.dataset.order})});$('ordersTable').addEventListener('keydown',e=>{if(e.key==='Enter'){const row=e.target.closest('[data-order]');if(row)openDetail({type:'order',id:row.dataset.order})}});$('closeDialog').onclick=()=>$('detailDialog').close();$('refreshDetail').onclick=()=>{if(detail)openDetail(detail)};$('helpButton').onclick=()=>$('helpDialog').showModal();$('closeHelp').onclick=()=>$('helpDialog').close();
$('reset').onclick=()=>{if(!confirm('이 탭의 가상 주문·입하·재고를 초기 상태로 되돌릴까요?'))return;s=E.createState();buildDocks();render();save();toast('초기 데모 센터로 돌아왔습니다.')};$('exportState').onclick=()=>{const out={kind:'virtual-fulfillment-center',exportedAt:new Date().toISOString(),layout:{floors:E.FLOOR_CONFIG,inboundDocks:3,outboundDocks:40},scope:'browser-local simulation; not connected to WMS or existing SQLite DB',state:s};const url=URL.createObjectURL(new Blob([JSON.stringify(out,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='가상물류센터_운영상태.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
setupLocations();buildDocks();selectFloor(0);render();let previous=performance.now(),lastDraw=0,lastUI=0;function frame(now){const delta=Math.max(0,Math.min(1,(now-previous)/1000));previous=now;if(!document.hidden&&s.running)E.advance(s,delta*s.speed);if(now-lastDraw>33&&!document.body.classList.contains('data-linked')){scene.draw(s);lastDraw=now}if(now-lastUI>650&&!document.body.classList.contains('data-linked')){render();lastUI=now}if(now-lastSave>3000){save();lastSave=now}requestAnimationFrame(frame)}requestAnimationFrame(frame);addEventListener('pagehide',save);
window.VirtualCenter={getState:()=>JSON.parse(JSON.stringify(s)),validate:()=>E.validate(s)};
